def downgrade() -> None:
    """按依赖倒序删表。

    这里刻意不调用 op.drop_index：MySQL 会为外键自动建索引，而我们又显式建了同名列，
    自动生成的 drop_index 在 MySQL 上会报 1553（Cannot drop index: needed in a foreign
    key constraint）。直接删表即可连带清掉这些索引与外键。
    """
    for table in (
        "prompt_versions",
        "media_snapshots",
        "dependency_edges",
        "content_revisions",
        "clip_shots",
        "canvas_node_layout",
        "asset_references",
        "usage_records",
        "media_nodes",
        "delivery_records",
        "content_documents",
        "clips",
        "character_profiles",
        "canvas_nodes",
        "attempt_links",
        "sessions",
        "generation_attempts",
        "episodes",
        "assets",
        "users",
        "projects",
        "model_configs",
        "media_items",
        "generation_submissions",
    ):
        op.drop_table(table)
